    if (c != 0) {
        return c
    }
    c = d1.loc().end() - d2.loc().end()
    if (c != 0) {
        return c
    }
    c = d1.code() - d2.code()
    if (c != 0) {
        return c
    }
    c = com.xemantic.typescript.tsgo.go.slices.compare<String>(d1.messageArgs(), d2.messageArgs())
    if (c != 0) {
